#!/usr/bin/env node
import fs from 'node:fs';
import path from 'node:path';

const root = process.cwd();
const full = relative => path.join(root, relative);
const read = relative => fs.readFileSync(full(relative), 'utf8');
const write = (relative, content) => {
  fs.mkdirSync(path.dirname(full(relative)), { recursive: true });
  fs.writeFileSync(full(relative), content);
};
const readJson = relative => JSON.parse(read(relative));
const writeJson = (relative, value) => write(relative, JSON.stringify(value, null, 2) + '\n');
const generatedFiles = {"data/project/lake-allocator-war-estate-execution-wave-22-policy.json": "{\n  \"schema_version\": \"lake-allocator-war-estate-execution-wave-22-policy@1\",\n  \"program_ref\": \"CN-LAKE-ALLOCATOR-WAR-W22\",\n  \"wave_ref\": \"LAW-W22\",\n  \"as_of\": \"2026-07-31\",\n  \"title\": \"Allocator-war estate acquisition execution Wave 22\",\n  \"purpose\": \"Convert the eleven Wave 21 estate acquisition routes into deterministic estate-owned acquisition queues while preserving reviewed, split-authority, and unreviewed-intake states; retain controls, refusals, nulls, and zero graph or publication effect.\",\n  \"base_checkpoint\": {\n    \"branch\": \"agent/lake-allocator-war-wave-21\",\n    \"commit\": \"ec730441e4779b24226f12f556707f4a89b7fe3f\",\n    \"required_ancestry\": true\n  },\n  \"paths\": {\n    \"source_estate_registry\": \"data/project/lake-allocator-war-estate-acquisition-registry-wave-21.jsonl\",\n    \"projection\": \"build/lake-actions/allocator-war-estate-execution-wave-22.json\",\n    \"report\": \"reports/lake-allocator-war-estate-execution-wave-22.md\",\n    \"method\": \"docs/methods/lake-allocator-war-estate-execution-wave-22.md\",\n    \"milestone\": \"docs/milestones/lake-allocator-war-estate-execution-wave-22.md\"\n  },\n  \"expected_counts\": {\n    \"estate_queues\": 11,\n    \"acquisition_tasks\": 52,\n    \"reviewed_only_queues\": 3,\n    \"split_authority_queues\": 5,\n    \"unreviewed_only_queues\": 3,\n    \"finding_promotions\": 0,\n    \"graph_effects\": 0,\n    \"publication_clearances\": 0\n  },\n  \"authority_law\": {\n    \"reviewed_wave_01_routing\": {\n      \"queue_class\": \"reviewed_execution_queue\",\n      \"task_authority\": \"maintainer_reviewed_routing_below_second_party_review\"\n    },\n    \"split_reviewed_wave_01_and_unreviewed_wave_02\": {\n      \"queue_class\": \"split_authority_execution_queue\",\n      \"task_authority\": \"split_reviewed_and_unreviewed_sources\"\n    },\n    \"unreviewed_wave_02_acquisition_only\": {\n      \"queue_class\": \"unreviewed_acquisition_queue\",\n      \"task_authority\": \"unreviewed_intake_acquisition_only\"\n    }\n  },\n  \"priority_law\": {\n    \"order\": [\n      \"P0\",\n      \"P1\",\n      \"P2\"\n    ],\n    \"keywords\": {\n      \"P0\": [\n        \"denominator\",\n        \"universe\",\n        \"inventory\",\n        \"remand\",\n        \"correction\",\n        \"appeal\",\n        \"litigation\",\n        \"roster\",\n        \"affected-person\",\n        \"affected rows\",\n        \"outcome records\",\n        \"practical access\"\n      ],\n      \"P1\": [\n        \"terms\",\n        \"rights\",\n        \"evaluation\",\n        \"foci\",\n        \"committee\",\n        \"contract\",\n        \"interface\",\n        \"ip schedules\",\n        \"data-rights\",\n        \"weights\",\n        \"custody\",\n        \"rejected rows\",\n        \"selected\",\n        \"applicant\",\n        \"bidder\",\n        \"candidate\",\n        \"selection history\",\n        \"notice\",\n        \"rationale\"\n      ]\n    },\n    \"outputs\": {\n      \"P0\": \"Complete denominator-and-correction ledger with included, excluded, null, unavailable, appealed, and resolved rows.\",\n      \"P1\": \"Operative selector-and-rights ledger with exact criteria, custody, selected and nonselected rows, instruments, exceptions, and review routes.\",\n      \"P2\": \"Longitudinal consequence ledger with performance, failure, substitution, recurrence, recovery, and explicit no-observed-effect controls.\"\n    },\n    \"closure_tests\": {\n      \"P0\": \"The declared denominator and correction route are complete for the bounded window, every missing row has an explicit availability disposition, and no unresolved exclusion is silently treated as a null.\",\n      \"P1\": \"The operative rule or instrument, decision custody, comparator rows, exceptions, and appeal route are source-addressed and reversible.\",\n      \"P2\": \"The bounded outcome window includes selected, nonselected, failed, substituted, recovered, and explicit no-observed-effect rows with dated provenance.\"\n    }\n  },\n  \"task_contract\": {\n    \"allowed_results\": [\n      \"supported\",\n      \"contradicted\",\n      \"mixed\",\n      \"no_observed_effect\",\n      \"unavailable_after_search\",\n      \"outside_bounded_window\"\n    ],\n    \"blocked_promotions\": [\n      \"estate_finding\",\n      \"complete_compact_finding\",\n      \"racial_order_finding\",\n      \"prevalence_finding\",\n      \"coordination_finding\",\n      \"common_purpose_finding\",\n      \"identity_edge\",\n      \"relationship_edge\",\n      \"participation_row\",\n      \"active_claim\",\n      \"hop_edge\",\n      \"publication_clearance\"\n    ],\n    \"controls_and_refusals_required\": true,\n    \"finding_promoted\": false,\n    \"graph_effect\": \"none\",\n    \"publication_status\": \"blocked\"\n  },\n  \"boundaries\": {\n    \"queue_admission_is_estate_adoption\": false,\n    \"queue_admission_is_evidence_review\": false,\n    \"reviewed_route_is_second_party_review\": false,\n    \"split_route_launders_unreviewed_intake\": false,\n    \"unreviewed_route_may_promote_finding\": false,\n    \"priority_is_merit_or_truth_score\": false,\n    \"task_recurrence_is_prevalence\": false,\n    \"shared_consumer_is_relationship\": false,\n    \"identity_created\": false,\n    \"relationship_created\": false,\n    \"participation_created\": false,\n    \"active_claim_created\": false,\n    \"hop_created\": false,\n    \"publication_cleared\": false,\n    \"graph_effect\": \"none\"\n  }\n}\n", "tools/build-lake-allocator-war-estate-execution-wave-22.mjs": "#!/usr/bin/env node\nimport crypto from 'node:crypto';\nimport fs from 'node:fs';\nimport path from 'node:path';\nimport { fileURLToPath } from 'node:url';\n\nconst root = process.cwd();\nconst full = relative => path.join(root, relative);\nconst readJson = relative => JSON.parse(fs.readFileSync(full(relative), 'utf8'));\nconst readJsonl = relative => fs.readFileSync(full(relative), 'utf8').split(/\\r?\\n/).filter(Boolean).map(line => JSON.parse(line));\nconst writeJson = (relative, value) => {\n  fs.mkdirSync(path.dirname(full(relative)), { recursive: true });\n  fs.writeFileSync(full(relative), JSON.stringify(value, null, 2) + '\\n');\n};\nconst digestBytes = value => crypto.createHash('sha256').update(value).digest('hex');\nconst stable = value => {\n  if (Array.isArray(value)) return value.map(stable);\n  if (!value || typeof value !== 'object') return value;\n  return Object.fromEntries(Object.keys(value).sort().map(key => [key, stable(value[key])]));\n};\nconst digest = value => digestBytes(JSON.stringify(stable(value)));\nconst countBy = (rows, key) => Object.fromEntries(\n  [...new Set(rows.map(row => row[key]))].sort().map(value => [value, rows.filter(row => row[key] === value).length])\n);\n\nexport function priorityFor(target, policy) {\n  const normalized = String(target).toLowerCase();\n  for (const tier of ['P0', 'P1']) {\n    if (policy.priority_law.keywords[tier].some(keyword => normalized.includes(keyword))) return tier;\n  }\n  return 'P2';\n}\n\nfunction graphDigests() {\n  return {\n    participation_sha256: digest(readJsonl('data/ledger/participation.jsonl')),\n    active_claims_sha256: digest(readJson('build/axm-identity.json').claims),\n    hop_edges_sha256: digest(readJson('build/hop-graph.json').edges),\n    rejected_hop_surfaces_sha256: digest(readJson('build/hop-graph.json').rejected_hop_surfaces),\n    rejected_hop_pairs_sha256: digest(readJson('build/hop-graph.json').rejected_hop_pairs)\n  };\n}\n\nexport function buildProjection(policy, sourceRows, sourceRaw) {\n  const queues = sourceRows\n    .slice()\n    .sort((a, b) => a.allocator_estate_feed_id.localeCompare(b.allocator_estate_feed_id))\n    .map(source => {\n      const authority = policy.authority_law[source.route_authority];\n      if (!authority) throw new Error(source.allocator_estate_feed_id + ': unknown route authority');\n      const tasks = source.next_acquisition.map((target, index) => {\n        const priority = priorityFor(target, policy);\n        return {\n          task_ref: source.allocator_estate_feed_id + '/T' + String(index + 1).padStart(2, '0'),\n          sequence: index + 1,\n          acquisition_target: target,\n          priority_tier: priority,\n          task_authority: authority.task_authority,\n          required_output: policy.priority_law.outputs[priority] + ' Target: ' + target,\n          closure_test: policy.priority_law.closure_tests[priority],\n          allowed_results: policy.task_contract.allowed_results,\n          controls_and_refusals_required: source.controls_and_refusals_required === true,\n          blocked_promotions: policy.task_contract.blocked_promotions,\n          finding_promoted: false,\n          graph_effect: 'none',\n          publication_status: 'blocked'\n        };\n      });\n      return {\n        allocator_estate_feed_id: source.allocator_estate_feed_id,\n        consumer_key: source.consumer_key,\n        source_route_authority: source.route_authority,\n        queue_class: authority.queue_class,\n        task_authority: authority.task_authority,\n        consumer_question: source.consumer_question,\n        reviewed_source_finding_refs: source.reviewed_source_finding_refs,\n        reviewed_source_observation_refs: source.reviewed_source_observation_refs,\n        unreviewed_intake_observation_refs: source.unreviewed_intake_observation_refs,\n        supplies: source.supplies,\n        controls_and_refusals_required: source.controls_and_refusals_required === true,\n        task_count: tasks.length,\n        tasks,\n        finding_promoted: false,\n        graph_effect: 'none',\n        publication_status: 'blocked'\n      };\n    });\n\n  const tasks = queues.flatMap(queue => queue.tasks);\n  return {\n    schema_version: 'lake-allocator-war-estate-execution-wave-22@1',\n    program_ref: policy.program_ref,\n    wave_ref: policy.wave_ref,\n    as_of: policy.as_of,\n    generated_from: {\n      policy_path: 'data/project/lake-allocator-war-estate-execution-wave-22-policy.json',\n      source_registry_path: policy.paths.source_estate_registry,\n      source_registry_bytes: Buffer.byteLength(sourceRaw),\n      source_registry_sha256: digestBytes(sourceRaw)\n    },\n    counts: {\n      estate_queues: queues.length,\n      acquisition_tasks: tasks.length,\n      authority_classes: countBy(queues, 'queue_class'),\n      priority_tiers: countBy(tasks, 'priority_tier'),\n      reviewed_only_queues: queues.filter(row => row.queue_class === 'reviewed_execution_queue').length,\n      split_authority_queues: queues.filter(row => row.queue_class === 'split_authority_execution_queue').length,\n      unreviewed_only_queues: queues.filter(row => row.queue_class === 'unreviewed_acquisition_queue').length,\n      finding_promotions: 0,\n      graph_effects: 0,\n      publication_clearances: 0\n    },\n    graph_digests: graphDigests(),\n    queues,\n    boundaries: policy.boundaries\n  };\n}\n\nfunction renderReport(projection) {\n  const lines = [\n    '# Allocator-war estate execution Wave 22',\n    '',\n    '```text',\n    'estate queues:              ' + projection.counts.estate_queues,\n    'acquisition tasks:          ' + projection.counts.acquisition_tasks,\n    'reviewed-only queues:       ' + projection.counts.reviewed_only_queues,\n    'split-authority queues:     ' + projection.counts.split_authority_queues,\n    'unreviewed-only queues:     ' + projection.counts.unreviewed_only_queues,\n    'finding promotions:         0',\n    'graph effects:              0',\n    'publication clearances:     0',\n    '```',\n    '',\n    '| Estate consumer | Feed | Authority | Tasks | P0 | P1 | P2 |',\n    '|---|---|---|---:|---:|---:|---:|'\n  ];\n  for (const queue of projection.queues) {\n    const priorities = {\n      P0: queue.tasks.filter(task => task.priority_tier === 'P0').length,\n      P1: queue.tasks.filter(task => task.priority_tier === 'P1').length,\n      P2: queue.tasks.filter(task => task.priority_tier === 'P2').length\n    };\n    lines.push(\n      '| ' + queue.consumer_key + ' | ' + queue.allocator_estate_feed_id + ' | ' +\n      queue.queue_class + ' | ' + queue.task_count + ' | ' +\n      priorities.P0 + ' | ' + priorities.P1 + ' | ' + priorities.P2 + ' |'\n    );\n  }\n  lines.push(\n    '',\n    'Priority orders acquisition work. It is not a truth, merit, guilt, risk, or importance score.',\n    '',\n    'Every queue remains below estate adoption. Unreviewed intake remains acquisition-only; controls, nulls, refusals, and failed paths remain mandatory. Graph effect is none and publication remains blocked.',\n    ''\n  );\n  return lines.join('\\n');\n}\n\nexport function buildRepository() {\n  const policyPath = 'data/project/lake-allocator-war-estate-execution-wave-22-policy.json';\n  const policy = readJson(policyPath);\n  const sourceRaw = fs.readFileSync(full(policy.paths.source_estate_registry), 'utf8');\n  const sourceRows = sourceRaw.split(/\\r?\\n/).filter(Boolean).map(line => JSON.parse(line));\n  const projection = buildProjection(policy, sourceRows, sourceRaw);\n  writeJson(policy.paths.projection, projection);\n  fs.mkdirSync(path.dirname(full(policy.paths.report)), { recursive: true });\n  fs.writeFileSync(full(policy.paths.report), renderReport(projection));\n  console.log('allocator-war estate execution Wave 22 built');\n  console.log('  estate queues / acquisition tasks: ' + projection.counts.estate_queues + ' / ' + projection.counts.acquisition_tasks);\n  console.log('  reviewed / split / unreviewed queues: ' + projection.counts.reviewed_only_queues + ' / ' + projection.counts.split_authority_queues + ' / ' + projection.counts.unreviewed_only_queues);\n  console.log('  graph/publication findings: 0/0');\n  return projection;\n}\n\nif (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {\n  buildRepository();\n}\n", "tools/validate-lake-allocator-war-estate-execution-wave-22.mjs": "#!/usr/bin/env node\nimport crypto from 'node:crypto';\nimport fs from 'node:fs';\nimport path from 'node:path';\nimport { execFileSync } from 'node:child_process';\nimport { fileURLToPath } from 'node:url';\nimport { priorityFor } from './build-lake-allocator-war-estate-execution-wave-22.mjs';\n\nconst defaultRoot = process.cwd();\nconst full = (root, relative) => path.join(root, relative);\nconst readJson = (root, relative) => JSON.parse(fs.readFileSync(full(root, relative), 'utf8'));\nconst readJsonl = (root, relative) => fs.readFileSync(full(root, relative), 'utf8').split(/\\r?\\n/).filter(Boolean).map(line => JSON.parse(line));\nconst digestBytes = value => crypto.createHash('sha256').update(value).digest('hex');\nconst stable = value => {\n  if (Array.isArray(value)) return value.map(stable);\n  if (!value || typeof value !== 'object') return value;\n  return Object.fromEntries(Object.keys(value).sort().map(key => [key, stable(value[key])]));\n};\nconst digest = value => digestBytes(JSON.stringify(stable(value)));\nconst same = (left, right) => JSON.stringify(left) === JSON.stringify(right);\nconst unique = values => new Set(values).size === values.length;\nfunction fail(errors, message) { errors.push(message); }\nfunction countBy(rows, key) {\n  return Object.fromEntries(\n    [...new Set(rows.map(row => row[key]))].sort().map(value => [value, rows.filter(row => row[key] === value).length])\n  );\n}\nfunction graphDigests(root) {\n  return {\n    participation_sha256: digest(readJsonl(root, 'data/ledger/participation.jsonl')),\n    active_claims_sha256: digest(readJson(root, 'build/axm-identity.json').claims),\n    hop_edges_sha256: digest(readJson(root, 'build/hop-graph.json').edges),\n    rejected_hop_surfaces_sha256: digest(readJson(root, 'build/hop-graph.json').rejected_hop_surfaces),\n    rejected_hop_pairs_sha256: digest(readJson(root, 'build/hop-graph.json').rejected_hop_pairs)\n  };\n}\nfunction walk(value, visit, pointer = '$') {\n  if (Array.isArray(value)) {\n    value.forEach((item, index) => walk(item, visit, pointer + '[' + index + ']'));\n    return;\n  }\n  if (!value || typeof value !== 'object') return;\n  for (const [key, item] of Object.entries(value)) {\n    visit(key, item, pointer + '.' + key);\n    walk(item, visit, pointer + '.' + key);\n  }\n}\nfunction requiredWave21BasinPaths(policy) {\n  return {\n    'allocator-war-source': [\n      'data/project/lake-allocator-war-estate-execution-wave-22-policy.json',\n      policy.paths.method,\n      policy.paths.milestone\n    ],\n    'allocator-war-lake-actions': [policy.paths.projection],\n    'allocator-war-reports': [policy.paths.report]\n  };\n}\nfunction authorityCounts(sourceRows, policy) {\n  const queues = sourceRows.map(row => ({\n    queue_class: policy.authority_law[row.route_authority]?.queue_class ?? 'unknown'\n  }));\n  return countBy(queues, 'queue_class');\n}\n\nexport function validateArtifacts(state) {\n  const { policy, sourceRows, sourceRaw, projection, wave21Policy } = state;\n  const errors = [];\n  const expected = policy.expected_counts;\n\n  if (policy.schema_version !== 'lake-allocator-war-estate-execution-wave-22-policy@1') fail(errors, 'policy schema drift');\n  if (projection.schema_version !== 'lake-allocator-war-estate-execution-wave-22@1') fail(errors, 'projection schema drift');\n  if (projection.program_ref !== policy.program_ref || projection.wave_ref !== policy.wave_ref) fail(errors, 'program or wave reference drift');\n  if (policy.boundaries.graph_effect !== 'none' || projection.boundaries?.graph_effect !== 'none') fail(errors, 'graph boundary drift');\n  if (policy.boundaries.publication_cleared !== false) fail(errors, 'publication boundary drift');\n  if (sourceRows.length !== expected.estate_queues) fail(errors, 'source estate queue denominator drift');\n  if (!unique(sourceRows.map(row => row.allocator_estate_feed_id))) fail(errors, 'duplicate source estate feed');\n  if (sourceRows.reduce((sum, row) => sum + row.next_acquisition.length, 0) !== expected.acquisition_tasks) fail(errors, 'source acquisition task denominator drift');\n\n  const recognizedAuthorities = new Set(Object.keys(policy.authority_law));\n  if (sourceRows.some(row => !recognizedAuthorities.has(row.route_authority))) fail(errors, 'unknown source route authority');\n  if (sourceRows.some(row => row.controls_and_refusals_required !== true || row.finding_promoted !== false || row.graph_effect !== 'none')) {\n    fail(errors, 'source route boundary drift');\n  }\n  for (const row of sourceRows.filter(row => row.route_authority === 'unreviewed_wave_02_acquisition_only')) {\n    if (row.reviewed_source_finding_refs.length || row.reviewed_source_observation_refs.length) fail(errors, row.allocator_estate_feed_id + ': unreviewed route carries reviewed authority');\n    if (!row.unreviewed_intake_observation_refs.length) fail(errors, row.allocator_estate_feed_id + ': unreviewed route lacks intake source');\n  }\n\n  if (projection.generated_from?.source_registry_path !== policy.paths.source_estate_registry) fail(errors, 'source registry path drift');\n  if (projection.generated_from?.source_registry_bytes !== Buffer.byteLength(sourceRaw)) fail(errors, 'source registry byte count drift');\n  if (projection.generated_from?.source_registry_sha256 !== digestBytes(sourceRaw)) fail(errors, 'source registry sha256 drift');\n  if (projection.queues.length !== expected.estate_queues) fail(errors, 'projection queue count drift');\n  if (!unique(projection.queues.map(row => row.allocator_estate_feed_id))) fail(errors, 'duplicate projected estate feed');\n\n  const sourceByFeed = new Map(sourceRows.map(row => [row.allocator_estate_feed_id, row]));\n  const taskRefs = [];\n  const projectedTasks = [];\n  for (const queue of projection.queues) {\n    const source = sourceByFeed.get(queue.allocator_estate_feed_id);\n    if (!source) {\n      fail(errors, queue.allocator_estate_feed_id + ': projected queue has no source');\n      continue;\n    }\n    const authority = policy.authority_law[source.route_authority];\n    if (queue.consumer_key !== source.consumer_key) fail(errors, queue.allocator_estate_feed_id + ': consumer drift');\n    if (queue.source_route_authority !== source.route_authority) fail(errors, queue.allocator_estate_feed_id + ': source authority drift');\n    if (queue.queue_class !== authority.queue_class || queue.task_authority !== authority.task_authority) fail(errors, queue.allocator_estate_feed_id + ': queue authority classification drift');\n    if (queue.consumer_question !== source.consumer_question) fail(errors, queue.allocator_estate_feed_id + ': consumer question drift');\n    for (const key of ['reviewed_source_finding_refs', 'reviewed_source_observation_refs', 'unreviewed_intake_observation_refs', 'supplies']) {\n      if (!same(queue[key], source[key])) fail(errors, queue.allocator_estate_feed_id + ': ' + key + ' drift');\n    }\n    if (queue.controls_and_refusals_required !== true || queue.finding_promoted !== false || queue.graph_effect !== 'none' || queue.publication_status !== 'blocked') {\n      fail(errors, queue.allocator_estate_feed_id + ': queue boundary drift');\n    }\n    if (queue.task_count !== source.next_acquisition.length || queue.tasks.length !== source.next_acquisition.length) fail(errors, queue.allocator_estate_feed_id + ': task count drift');\n\n    queue.tasks.forEach((task, index) => {\n      projectedTasks.push(task);\n      taskRefs.push(task.task_ref);\n      const expectedRef = queue.allocator_estate_feed_id + '/T' + String(index + 1).padStart(2, '0');\n      const expectedTarget = source.next_acquisition[index];\n      const priority = priorityFor(expectedTarget, policy);\n      if (task.task_ref !== expectedRef) fail(errors, expectedRef + ': task reference drift');\n      if (task.sequence !== index + 1) fail(errors, expectedRef + ': task sequence drift');\n      if (task.acquisition_target !== expectedTarget) fail(errors, expectedRef + ': acquisition target drift');\n      if (task.priority_tier !== priority) fail(errors, expectedRef + ': priority drift');\n      if (task.task_authority !== authority.task_authority) fail(errors, expectedRef + ': task authority drift');\n      if (task.required_output !== policy.priority_law.outputs[priority] + ' Target: ' + expectedTarget) fail(errors, expectedRef + ': required output drift');\n      if (task.closure_test !== policy.priority_law.closure_tests[priority]) fail(errors, expectedRef + ': closure test drift');\n      if (!same(task.allowed_results, policy.task_contract.allowed_results)) fail(errors, expectedRef + ': allowed results drift');\n      if (!same(task.blocked_promotions, policy.task_contract.blocked_promotions)) fail(errors, expectedRef + ': blocked promotions drift');\n      if (task.controls_and_refusals_required !== true || task.finding_promoted !== false || task.graph_effect !== 'none' || task.publication_status !== 'blocked') {\n        fail(errors, expectedRef + ': task boundary drift');\n      }\n    });\n  }\n  if (!unique(taskRefs)) fail(errors, 'duplicate task reference');\n  if (projectedTasks.length !== expected.acquisition_tasks) fail(errors, 'projected task denominator drift');\n\n  const expectedAuthorityCounts = authorityCounts(sourceRows, policy);\n  if (!same(projection.counts.authority_classes, expectedAuthorityCounts)) fail(errors, 'authority class count drift');\n  if (!same(projection.counts.priority_tiers, countBy(projectedTasks, 'priority_tier'))) fail(errors, 'priority tier count drift');\n  if (projection.counts.estate_queues !== expected.estate_queues || projection.counts.acquisition_tasks !== expected.acquisition_tasks) fail(errors, 'projection denominator count drift');\n  for (const key of ['reviewed_only_queues', 'split_authority_queues', 'unreviewed_only_queues', 'finding_promotions', 'graph_effects', 'publication_clearances']) {\n    if (projection.counts[key] !== expected[key]) fail(errors, key + ' count drift');\n  }\n\n  walk(projection, (key, _value, pointer) => {\n    if (/_id$/i.test(key) && key !== 'allocator_estate_feed_id') fail(errors, pointer + ': unauthorized new machine identifier key');\n  });\n\n  const requiredBasins = requiredWave21BasinPaths(policy);\n  for (const [basinRef, paths] of Object.entries(requiredBasins)) {\n    const basin = wave21Policy.basin_contract.find(row => row.basin_id === basinRef);\n    if (!basin) {\n      fail(errors, basinRef + ': Wave 21 basin absent');\n      continue;\n    }\n    for (const relative of paths) {\n      if (!basin.path_prefixes.includes(relative)) fail(errors, relative + ': Wave 22 path absent from ' + basinRef);\n      if (!basin.authoritative_entrypoints.includes(relative)) fail(errors, relative + ': Wave 22 authoritative entrypoint absent from ' + basinRef);\n    }\n  }\n  if (!wave21Policy.projection_contract.allowed_generated_paths.includes(policy.paths.projection)) fail(errors, 'Wave 22 projection absent from Wave 21 generated-path contract');\n  if (wave21Policy.boundaries.wave_21_basin_paths_are_exact !== true) fail(errors, 'Wave 21 exact basin boundary drift');\n\n  return errors;\n}\n\nexport function validateRepository(root = defaultRoot) {\n  const policyPath = 'data/project/lake-allocator-war-estate-execution-wave-22-policy.json';\n  const policy = readJson(root, policyPath);\n  const sourceRaw = fs.readFileSync(full(root, policy.paths.source_estate_registry), 'utf8');\n  const sourceRows = sourceRaw.split(/\\r?\\n/).filter(Boolean).map(line => JSON.parse(line));\n  const projection = readJson(root, policy.paths.projection);\n  const wave21Policy = readJson(root, 'data/project/lake-allocator-war-wave-21-policy.json');\n  const errors = validateArtifacts({ policy, sourceRows, sourceRaw, projection, wave21Policy });\n\n  if (process.env.LAW22_SKIP_GIT !== '1') {\n    try {\n      execFileSync('git', ['merge-base', '--is-ancestor', policy.base_checkpoint.commit, 'HEAD'], { cwd: root, stdio: 'ignore' });\n    } catch {\n      fail(errors, 'Wave 22 base checkpoint is not an ancestor');\n    }\n  }\n\n  for (const relative of [policy.paths.report, policy.paths.method, policy.paths.milestone]) {\n    if (!fs.existsSync(full(root, relative))) fail(errors, relative + ': required Wave 22 artifact absent');\n  }\n  if (fs.existsSync(full(root, policy.paths.report))) {\n    const report = fs.readFileSync(full(root, policy.paths.report), 'utf8');\n    if (!report.includes('acquisition tasks:          ' + policy.expected_counts.acquisition_tasks)) fail(errors, 'Wave 22 report task count drift');\n    if (!report.includes('graph effects:              0')) fail(errors, 'Wave 22 report graph boundary drift');\n  }\n\n  if (!same(projection.graph_digests, graphDigests(root))) fail(errors, 'Wave 22 changed participation, active claims, hop edges, or rejected-hop controls');\n\n  const requiredRoots = [\n    policyPath,\n    policy.paths.projection,\n    policy.paths.report,\n    policy.paths.method,\n    policy.paths.milestone\n  ];\n  const lakePolicy = readJson(root, 'data/project/lake-index-policy.json');\n  for (const relative of requiredRoots) if (!lakePolicy.authoritative_roots.includes(relative)) fail(errors, relative + ': missing authoritative root');\n\n  const basinRegistry = readJson(root, 'data/project/lake-basin-registry.json');\n  const registryByRef = new Map(basinRegistry.basins.map(row => [row.basin_id, row]));\n  for (const basin of wave21Policy.basin_contract) {\n    if (['allocator-war-source', 'allocator-war-lake-actions', 'allocator-war-reports'].includes(basin.basin_id) && !same(registryByRef.get(basin.basin_id), basin)) {\n      fail(errors, basin.basin_id + ': installed basin contract drift');\n    }\n  }\n\n  const pkg = readJson(root, 'package.json');\n  if (!pkg.scripts['build:lake-allocator-war-estate-execution-wave-22']) fail(errors, 'Wave 22 builder script absent');\n  if (!pkg.scripts['validate:lake-allocator-war-estate-execution-wave-22']) fail(errors, 'Wave 22 validator script absent');\n  if (!pkg.scripts.check.includes('validate:lake-allocator-war-estate-execution-wave-22')) fail(errors, 'Wave 22 absent from complete release gate');\n\n  const installerText = fs.readFileSync(full(root, 'tools/install-lake-allocator-war-wave-21.mjs'), 'utf8');\n  const wave21ValidatorText = fs.readFileSync(full(root, 'tools/validate-lake-allocator-war-wave-21.mjs'), 'utf8');\n  for (const relative of requiredRoots) {\n    if (!installerText.includes(relative)) fail(errors, relative + ': Wave 21 installer does not preserve Wave 22 root');\n    if (!wave21ValidatorText.includes(relative)) fail(errors, relative + ': Wave 21 validator does not preserve Wave 22 root');\n  }\n\n  if (process.env.LAW22_SKIP_SHARDS !== '1') {\n    const membershipPath = 'build/lake-index/basin-membership.jsonl';\n    const objectIndexPath = 'build/lake-object-index.json';\n    const summaryPath = 'build/lake-index/summary.json';\n    const gapsPath = 'build/lake-index/gap-summary.json';\n    if (fs.existsSync(full(root, membershipPath))) {\n      const membership = readJsonl(root, membershipPath);\n      const byPath = new Map(membership.map(row => [row.path, row]));\n      for (const relative of [policyPath, policy.paths.method, policy.paths.milestone]) {\n        if (byPath.get(relative)?.basin_id !== 'allocator-war-source') fail(errors, relative + ': wrong Wave 22 source basin');\n      }\n      if (byPath.get(policy.paths.projection)?.basin_id !== 'allocator-war-lake-actions') fail(errors, 'Wave 22 projection wrong basin');\n      if (byPath.get(policy.paths.report)?.basin_id !== 'allocator-war-reports') fail(errors, 'Wave 22 report wrong basin');\n    }\n    if (fs.existsSync(full(root, objectIndexPath))) {\n      const objects = readJson(root, objectIndexPath).objects ?? [];\n      const byCompound = new Map(objects.map(row => [row.id_key + ':' + row.id_value, row]));\n      for (const row of sourceRows) {\n        const object = byCompound.get('allocator_estate_feed_id:' + row.allocator_estate_feed_id);\n        if (!object) {\n          fail(errors, row.allocator_estate_feed_id + ': lake object absent');\n          continue;\n        }\n        if (!(object.occurrences ?? []).some(item => item.path === policy.paths.projection && item.generated === true)) fail(errors, row.allocator_estate_feed_id + ': Wave 22 projection occurrence absent');\n        if (object.divergent_projections_unadjudicated) fail(errors, row.allocator_estate_feed_id + ': Wave 22 typed projection remains unadjudicated');\n      }\n    }\n    if (fs.existsSync(full(root, summaryPath))) {\n      const summary = readJson(root, summaryPath);\n      for (const key of ['unindexed_machine_ids_unadjudicated', 'source_ids_without_projection_unadjudicated', 'divergent_identifier_projections_unadjudicated']) {\n        if (summary.counts?.[key] !== 0) fail(errors, key + ': global residual reopened');\n      }\n    }\n    if (fs.existsSync(full(root, gapsPath))) {\n      const gaps = readJson(root, gapsPath);\n      for (const key of ['unindexed_machine_ids_unadjudicated', 'source_ids_without_projection_unadjudicated', 'divergent_identifier_projections_unadjudicated']) {\n        if (gaps.counts?.[key] !== 0) fail(errors, key + ': sharded residual reopened');\n      }\n    }\n  }\n\n  for (const temporary of [\n    '.github/tmp/lake-allocator-war-estate-execution-wave-22-trigger.json',\n    '.github/workflows/temporary-lake-allocator-war-estate-execution-wave-22-materializer.yml',\n    'tools/materialize-lake-allocator-war-estate-execution-wave-22.mjs'\n  ]) if (fs.existsSync(full(root, temporary))) fail(errors, temporary + ': temporary transport retained');\n\n  if (errors.length) throw new Error('allocator-war estate execution Wave 22 validation failed:\\n- ' + errors.join('\\n- '));\n  return {\n    queues: projection.counts.estate_queues,\n    tasks: projection.counts.acquisition_tasks,\n    priorities: projection.counts.priority_tiers,\n    authority: projection.counts.authority_classes\n  };\n}\n\nconst invoked = process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url);\nif (invoked) {\n  const result = validateRepository(defaultRoot);\n  console.log('allocator-war estate execution Wave 22 validation passed');\n  console.log('  estate queues / acquisition tasks: ' + result.queues + ' / ' + result.tasks);\n  console.log('  authority classes: ' + JSON.stringify(result.authority));\n  console.log('  priority tiers: ' + JSON.stringify(result.priorities));\n  console.log('  graph/publication findings: 0/0');\n}\n", "test/lake-allocator-war-estate-execution-wave-22.test.js": "#!/usr/bin/env node\nimport assert from 'node:assert/strict';\nimport fs from 'node:fs';\nimport os from 'node:os';\nimport path from 'node:path';\nimport { validateArtifacts } from '../tools/validate-lake-allocator-war-estate-execution-wave-22.mjs';\n\nconst root = process.cwd();\nconst readJson = relative => JSON.parse(fs.readFileSync(path.join(root, relative), 'utf8'));\nconst sourceRaw = fs.readFileSync(path.join(root, 'data/project/lake-allocator-war-estate-acquisition-registry-wave-21.jsonl'), 'utf8');\nconst sourceRows = sourceRaw.split(/\\r?\\n/).filter(Boolean).map(line => JSON.parse(line));\nconst baseline = {\n  policy: readJson('data/project/lake-allocator-war-estate-execution-wave-22-policy.json'),\n  sourceRows,\n  sourceRaw,\n  projection: readJson('build/lake-actions/allocator-war-estate-execution-wave-22.json'),\n  wave21Policy: readJson('data/project/lake-allocator-war-wave-21-policy.json')\n};\nconst clone = value => structuredClone(value);\nconst errorsFor = state => validateArtifacts(state);\nassert.deepEqual(errorsFor(clone(baseline)), [], 'Wave 22 baseline should validate');\n\nconst mutations = [\n  ['drop estate queue', state => { state.projection.queues.pop(); }],\n  ['duplicate estate feed', state => { state.projection.queues[1].allocator_estate_feed_id = state.projection.queues[0].allocator_estate_feed_id; }],\n  ['drop acquisition task', state => { state.projection.queues[0].tasks.pop(); }],\n  ['duplicate task reference', state => { state.projection.queues[0].tasks[1].task_ref = state.projection.queues[0].tasks[0].task_ref; }],\n  ['change priority', state => { state.projection.queues[0].tasks[0].priority_tier = 'P2'; }],\n  ['change acquisition target', state => { state.projection.queues[0].tasks[0].acquisition_target = 'invented target'; }],\n  ['inflate task authority', state => { state.projection.queues[0].tasks[0].task_authority = 'adjudicated'; }],\n  ['drop allowed result', state => { state.projection.queues[0].tasks[0].allowed_results.pop(); }],\n  ['drop blocked promotion', state => { state.projection.queues[0].tasks[0].blocked_promotions.pop(); }],\n  ['remove controls', state => { state.projection.queues[0].tasks[0].controls_and_refusals_required = false; }],\n  ['promote finding', state => { state.projection.queues[0].tasks[0].finding_promoted = true; }],\n  ['create graph effect', state => { state.projection.queues[0].tasks[0].graph_effect = 'edge'; }],\n  ['clear publication', state => { state.projection.queues[0].tasks[0].publication_status = 'cleared'; }],\n  ['change queue class', state => { state.projection.queues[0].queue_class = 'adjudicated_queue'; }],\n  ['unknown source authority', state => { state.sourceRows[0].route_authority = 'invented_authority'; }],\n  ['launder unreviewed source', state => {\n    const row = state.sourceRows.find(item => item.route_authority === 'unreviewed_wave_02_acquisition_only');\n    row.reviewed_source_observation_refs.push('SSC-OBS-0001');\n  }],\n  ['change source digest', state => { state.projection.generated_from.source_registry_sha256 = '0'.repeat(64); }],\n  ['inflate task count', state => { state.projection.counts.acquisition_tasks += 1; }],\n  ['remove generated path contract', state => {\n    state.wave21Policy.projection_contract.allowed_generated_paths =\n      state.wave21Policy.projection_contract.allowed_generated_paths.filter(item => item !== state.policy.paths.projection);\n  }],\n  ['remove source basin path', state => {\n    const basin = state.wave21Policy.basin_contract.find(item => item.basin_id === 'allocator-war-source');\n    basin.path_prefixes = basin.path_prefixes.filter(item => item !== 'data/project/lake-allocator-war-estate-execution-wave-22-policy.json');\n  }],\n  ['change expected task denominator', state => { state.policy.expected_counts.acquisition_tasks += 1; }],\n  ['introduce machine identifier', state => { state.projection.queues[0].tasks[0].invented_id = 'LAW22-X'; }]\n];\n\nfor (const [label, mutate] of mutations) {\n  const state = clone(baseline);\n  mutate(state);\n  const errors = errorsFor(state);\n  assert.ok(errors.length > 0, label + ': mutation was not rejected');\n}\n\nconsole.log('allocator-war estate execution Wave 22 adversarial mutations passed: ' + mutations.length);\n", ".github/workflows/lake-allocator-war-estate-execution-wave-22.yml": "name: Allocator-war estate execution Wave 22\n\non:\n  pull_request:\n    branches:\n      - agent/lake-allocator-war-wave-21\n    paths:\n      - '.github/workflows/lake-allocator-war-estate-execution-wave-22.yml'\n      - 'data/project/lake-allocator-war-estate-execution-wave-22-policy.json'\n      - 'data/project/lake-allocator-war-wave-21-policy.json'\n      - 'data/project/lake-basin-registry.json'\n      - 'data/project/lake-index-policy.json'\n      - 'tools/*lake-allocator-war*wave-2*.mjs'\n      - 'test/lake-allocator-war-estate-execution-wave-22.test.js'\n      - 'docs/methods/lake-allocator-war-estate-execution-wave-22.md'\n      - 'docs/milestones/lake-allocator-war-estate-execution-wave-22.md'\n      - 'build/lake-actions/allocator-war-estate-execution-wave-22.json'\n      - 'reports/lake-allocator-war-estate-execution-wave-22.md'\n      - 'package.json'\n  push:\n    branches:\n      - agent/allocator-war-estate-acquisition-wave-22\n    paths:\n      - '.github/workflows/lake-allocator-war-estate-execution-wave-22.yml'\n      - 'data/project/lake-allocator-war-estate-execution-wave-22-policy.json'\n      - 'data/project/lake-allocator-war-wave-21-policy.json'\n      - 'data/project/lake-basin-registry.json'\n      - 'data/project/lake-index-policy.json'\n      - 'tools/*lake-allocator-war*wave-2*.mjs'\n      - 'test/lake-allocator-war-estate-execution-wave-22.test.js'\n      - 'docs/methods/lake-allocator-war-estate-execution-wave-22.md'\n      - 'docs/milestones/lake-allocator-war-estate-execution-wave-22.md'\n      - 'build/lake-actions/allocator-war-estate-execution-wave-22.json'\n      - 'reports/lake-allocator-war-estate-execution-wave-22.md'\n      - 'package.json'\n  workflow_dispatch:\n\npermissions:\n  contents: read\n\nconcurrency:\n  group: lake-allocator-war-estate-execution-wave-22-${{ github.head_ref || github.ref_name }}\n  cancel-in-progress: false\n\njobs:\n  validate:\n    runs-on: ubuntu-latest\n    timeout-minutes: 60\n    steps:\n      - uses: actions/checkout@v4\n        with:\n          fetch-depth: 0\n\n      - uses: actions/setup-node@v4\n        with:\n          node-version: '24'\n\n      - name: Await sealed materialization when source-only\n        id: state\n        shell: bash\n        run: |\n          if test -f build/lake-actions/allocator-war-estate-execution-wave-22.json; then\n            echo 'materialized=true' >> \"$GITHUB_OUTPUT\"\n          else\n            echo 'materialized=false' >> \"$GITHUB_OUTPUT\"\n            node --check tools/build-lake-allocator-war-estate-execution-wave-22.mjs\n            node --check tools/validate-lake-allocator-war-estate-execution-wave-22.mjs\n          fi\n\n      - name: Validate estate acquisition queues\n        if: steps.state.outputs.materialized == 'true'\n        run: node tools/validate-lake-allocator-war-estate-execution-wave-22.mjs\n\n      - name: Run adversarial mutations\n        if: steps.state.outputs.materialized == 'true'\n        run: node test/lake-allocator-war-estate-execution-wave-22.test.js\n\n      - name: Run complete repository release gate\n        if: steps.state.outputs.materialized == 'true'\n        run: npm run release:check\n\n      - name: Restore and validate committed lake epoch\n        if: steps.state.outputs.materialized == 'true'\n        shell: bash\n        run: |\n          set -euo pipefail\n          git restore --worktree .\n          git clean -fd\n          node tools/validate-lake-index-shards.mjs\n          node tools/validate-lake-basin-index.mjs\n          node tools/validate-lake-residual-frontier-wave-17.mjs\n          node tools/validate-lake-identifier-topology-wave-18.mjs\n          node tools/validate-lake-generator-contracts-wave-19.mjs\n          node tools/validate-lake-receipt-custody-wave-20.mjs\n          node tools/validate-lake-allocator-war-wave-21.mjs\n          node test/lake-allocator-war-wave-21.test.js\n          node tools/validate-lake-allocator-war-estate-execution-wave-22.mjs\n          node test/lake-allocator-war-estate-execution-wave-22.test.js\n          git diff --check\n          test -z \"$(git status --porcelain)\"\n", "docs/methods/lake-allocator-war-estate-execution-wave-22.md": "# Allocator-war estate acquisition execution \u2014 Wave 22\n\nWave 22 converts the eleven estate referrals admitted by Wave 21 into deterministic acquisition queues. It does not acquire the external records itself and it does not promote an estate finding. Its job is to make the next evidentiary work executable, ordered, source-addressed, and fail-closed.\n\nEach Wave 21 estate feed remains the queue key. Every `next_acquisition` item becomes one task with a stable `task_ref`, source authority, required output, closure test, allowed terminal states, retained controls and refusals, and explicit blocked promotions. The transformation preserves the source feed\u2019s reviewed-only, split-authority, or unreviewed-acquisition-only state.\n\nPriority is an execution ordering, not a truth, merit, risk, guilt, or importance score.\n\n```text\nP0  denominator, affected population, option universe, correction, appeal, or final outcome\nP1  operative criteria, custody, terms, rights, selection, rejection, exception, or review instrument\nP2  longitudinal performance, failure, recurrence, substitution, exit, recovery, or null control\n```\n\nThe first matching priority class wins. Every task remains bounded by the estate consumer question and the source route. A task may terminate as supported, contradicted, mixed, no observed effect, unavailable after search, or outside the bounded window. None of those states self-promotes into the estate, compact, racial-order, prevalence, coordination, or common-purpose layers.\n\nThe queue compiler preserves the following constitutional distinctions:\n\n```text\nreviewed routing is below second-party review\nsplit routing does not launder unreviewed intake\nunreviewed intake authorizes acquisition only\ncontrols and refused inferences travel with supportive material\nqueue recurrence does not establish prevalence\nsame consumer does not create a relationship\ngraph effect: none\npublication: blocked\n```\n\nWave 22 uses the existing allocator-war source, lake-action, and report basins. Exact file paths are added to those basins. No new semantic basin, identity, relationship, participation, active claim, hop, finding, or publication authority is created.\n", "docs/milestones/lake-allocator-war-estate-execution-wave-22.md": "# Allocator-war estate acquisition execution Wave 22\n\nWave 22 turns the Wave 21 estate routing layer into an executable acquisition surface.\n\n```text\nsource estate feeds:                    11\ndeterministic estate queues:            11\nacquisition tasks:                      52\nreviewed-only queues:                    3\nsplit-authority queues:                  5\nunreviewed-only queues:                  3\nfinding promotions:                      0\ngraph effects:                           0\npublication clearances:                  0\n```\n\nEach task has a stable reference, deterministic priority, required output, closure test, allowed result states, and blocked promotion set. Queue admission does not establish estate adoption, evidentiary truth, second-party review, prevalence, coordination, common purpose, or a graph relationship.\n\nThe next transition is execution against external and repository source routes, with source bytes or stable official identifiers, dated denominators, explicit nulls, failed paths, controls, and correction outcomes retained.\n"};

function appendUnique(list, values) {
  for (const value of values) if (!list.includes(value)) list.push(value);
  list.sort();
}
function replaceRequired(source, before, after, label) {
  if (source.includes(after)) return source;
  const count = source.split(before).length - 1;
  if (count !== 1) throw new Error(label + ': expected one marker, saw ' + count);
  return source.replace(before, after);
}

for (const [relative, content] of Object.entries(generatedFiles)) write(relative, content);

const wave22PolicyPath = 'data/project/lake-allocator-war-estate-execution-wave-22-policy.json';
const wave22 = readJson(wave22PolicyPath);
const wave21PolicyPath = 'data/project/lake-allocator-war-wave-21-policy.json';
const wave21 = readJson(wave21PolicyPath);
const sourceBasin = wave21.basin_contract.find(row => row.basin_id === 'allocator-war-source');
const actionBasin = wave21.basin_contract.find(row => row.basin_id === 'allocator-war-lake-actions');
const reportBasin = wave21.basin_contract.find(row => row.basin_id === 'allocator-war-reports');
if (!sourceBasin || !actionBasin || !reportBasin) throw new Error('Wave 21 allocator basins absent');
appendUnique(sourceBasin.path_prefixes, [wave22PolicyPath, wave22.paths.method, wave22.paths.milestone]);
appendUnique(sourceBasin.authoritative_entrypoints, [wave22PolicyPath, wave22.paths.method, wave22.paths.milestone]);
appendUnique(actionBasin.path_prefixes, [wave22.paths.projection]);
appendUnique(actionBasin.authoritative_entrypoints, [wave22.paths.projection]);
appendUnique(reportBasin.path_prefixes, [wave22.paths.report]);
appendUnique(reportBasin.authoritative_entrypoints, [wave22.paths.report]);
appendUnique(wave21.projection_contract.allowed_generated_paths, [wave22.paths.projection]);
wave21.boundaries.wave_22_queue_admission_is_estate_adoption = false;
wave21.boundaries.wave_22_priority_is_merit_or_truth_score = false;
writeJson(wave21PolicyPath, wave21);

const basinRegistryPath = 'data/project/lake-basin-registry.json';
const basinRegistry = readJson(basinRegistryPath);
const replacementBasins = new Map(wave21.basin_contract.map(row => [row.basin_id, row]));
basinRegistry.basins = basinRegistry.basins.map(row => replacementBasins.get(row.basin_id) ?? row);
basinRegistry.boundaries.allocator_war_wave_22_queue_is_estate_adoption = false;
writeJson(basinRegistryPath, basinRegistry);

const lakePolicyPath = 'data/project/lake-index-policy.json';
const lakePolicy = readJson(lakePolicyPath);
appendUnique(lakePolicy.authoritative_roots, [
  wave22PolicyPath,
  wave22.paths.projection,
  wave22.paths.report,
  wave22.paths.method,
  wave22.paths.milestone
]);
lakePolicy.boundaries.allocator_war_wave_22_queue_is_estate_adoption = false;
lakePolicy.boundaries.allocator_war_wave_22_priority_is_merit_or_truth_score = false;
writeJson(lakePolicyPath, lakePolicy);

const packagePath = 'package.json';
const pkg = readJson(packagePath);
pkg.scripts['build:lake-allocator-war-estate-execution-wave-22'] = 'node tools/build-lake-allocator-war-estate-execution-wave-22.mjs';
pkg.scripts['validate:lake-allocator-war-estate-execution-wave-22'] = 'node tools/validate-lake-allocator-war-estate-execution-wave-22.mjs';
pkg.scripts['ci:lake-allocator-war-estate-execution-wave-22'] = 'npm run build:lake-allocator-war-estate-execution-wave-22 && npm run validate:lake-allocator-war-estate-execution-wave-22 && node test/lake-allocator-war-estate-execution-wave-22.test.js';
if (!pkg.scripts.check.includes('validate:lake-allocator-war-estate-execution-wave-22')) {
  const marker = 'npm run validate:lake-allocator-war-wave-21';
  if (!pkg.scripts.check.includes(marker)) throw new Error('Wave 21 release-gate marker absent');
  pkg.scripts.check = pkg.scripts.check.replace(marker, marker + ' && npm run validate:lake-allocator-war-estate-execution-wave-22');
}
